"""`.Principled`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = '.Principled'
KIND = 'ShaderNodeTree'


def build(lib):
    t = lib.new_group(NAME, KIND, props={})

    t.socket('OUTPUT', 'Shader', 'NodeSocketShader')
    t.socket('INPUT', 'Force visibility', 'NodeSocketInt')
    t.socket('INPUT', 'Dark', 'NodeSocketColor')
    t.socket('INPUT', 'Light', 'NodeSocketColor', default_value=(1.0, 1.0, 1.0, 1.0))
    t.socket('INPUT', 'Normal', 'NodeSocketColor')
    t.socket('INPUT', 'Normal alpha', 'NodeSocketFloat')
    t.socket('INPUT', 'Normal detail', 'NodeSocketColor')
    t.socket('INPUT', 'Normal detail alpha', 'NodeSocketFloat')
    t.socket('INPUT', 'Permalight mask', 'NodeSocketColor')
    t.socket('INPUT', 'Alpha mask', 'NodeSocketColor')
    t.socket('INPUT', 'Alpha mask alpha', 'NodeSocketFloat')
    t.socket('INPUT', 'Alpha mask bottom', 'NodeSocketColor')
    t.socket('INPUT', 'Alpha mask bottom alpha', 'NodeSocketFloat')
    t.socket('INPUT', 'Light alpha', 'NodeSocketFloat', default_value=1.0)
    t.socket('INPUT', 'Disable permalight mask', 'NodeSocketBool')
    t.socket('INPUT', 'Hidden', 'NodeSocketFloat', subtype='FACTOR', min_value=0.0, max_value=1.0)

    t.node('NodeGroupInput', 'Group Input', props={
        'location': (-1200.0, 0.0),
    })
    t.node('NodeGroupOutput', 'Group Output', props={
        'location': (1100.0, 0.0),
    })
    t.node('ShaderNodeBsdfPrincipled', 'Principled BSDF', props={
        'location': (0.0, 0.0),
    })
    t.node('ShaderNodeBsdfTransparent', 'hidden.transparent', props={
        'location': (700.0, -150.0),
        'label': 'hidden.transparent',
    })
    t.node('ShaderNodeMixShader', 'hidden.mix', props={
        'location': (880.0, 0.0),
        'label': 'hidden.mix',
    })

    t.link('Group Input', 'Light', 'Principled BSDF', 'Base Color')
    t.link('Group Input', 'Light alpha', 'Principled BSDF', 'Alpha')
    t.link('Principled BSDF', 'BSDF', 'hidden.mix', 'Shader')
    t.link('hidden.transparent', 'BSDF', 'hidden.mix', 'Shader_001')
    t.link('Group Input', 'Hidden', 'hidden.mix', 'Fac')
    t.link('hidden.mix', 'Shader', 'Group Output', 'Shader')
    return t
